package main

import (
	"context"
	"database/sql"
	"errors"
	"path/filepath"

	_ "github.com/mattn/go-sqlite3"
)

type Ledger struct {
	db *sql.DB
}

func NewLedger(dataDir string) *Ledger {
	db, err := sql.Open("sqlite3", filepath.Join(dataDir, "ledger.db")+"?_journal_mode=WAL")
	if err != nil {
		panic(err)
	}
	// SQLite writes are serialized through one connection. This also makes the
	// lookup-and-insert in CreatePending safe under concurrent HTTP requests.
	db.SetMaxOpenConns(1)

	if _, err := db.Exec(`CREATE TABLE IF NOT EXISTS transactions (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		key TEXT NOT NULL,
		account TEXT NOT NULL,
		amount INTEGER NOT NULL,
		status TEXT NOT NULL DEFAULT 'pending'
	)`); err != nil {
		panic(err)
	}
	if _, err := db.Exec(`CREATE TABLE IF NOT EXISTS accounts (
		name TEXT PRIMARY KEY,
		balance INTEGER NOT NULL DEFAULT 0
	)`); err != nil {
		panic(err)
	}

	// A unique index provides an additional database-level guard. Legacy
	// databases may already contain duplicate keys; those are still handled by
	// the transactional lookup in CreatePending, so do not make the service
	// unavailable merely because such historical rows exist.
	if _, err := db.Exec(`CREATE UNIQUE INDEX IF NOT EXISTS transactions_key_unique ON transactions(key)`); err != nil {
		if _, err := db.Exec(`CREATE INDEX IF NOT EXISTS transactions_key_lookup ON transactions(key)`); err != nil {
			panic(err)
		}
	}

	return &Ledger{db: db}
}

type pendingTx struct {
	id      int64
	key     string
	account string
	amount  int
}

func (l *Ledger) Recover() {
	// Close the read cursor before opening write transactions; this is required
	// when the pool is limited to a single SQLite connection.
	rows, err := l.db.Query("SELECT id, key, account, amount FROM transactions WHERE status = 'pending' ORDER BY id")
	if err != nil {
		panic(err)
	}

	var pending []pendingTx
	for rows.Next() {
		var tx pendingTx
		if err := rows.Scan(&tx.id, &tx.key, &tx.account, &tx.amount); err != nil {
			rows.Close()
			panic(err)
		}
		pending = append(pending, tx)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		panic(err)
	}
	rows.Close()

	for _, tx := range pending {
		l.processOne(TxRequest{ID: tx.id, Key: tx.key, Account: tx.account, Amount: tx.amount})
	}
}

// CreatePending inserts a new pending transaction, or returns the ID of the
// transaction already associated with the key. The entire check-and-insert is
// transactional, so concurrent submissions cannot both create the key.
func (l *Ledger) CreatePending(key, account string, amount int) int64 {
	tx, err := l.db.BeginTx(context.Background(), nil)
	if err != nil {
		panic(err)
	}
	defer tx.Rollback()

	var id int64
	err = tx.QueryRow("SELECT id FROM transactions WHERE key = ? ORDER BY id LIMIT 1", key).Scan(&id)
	if err == nil {
		if err := tx.Commit(); err != nil {
			panic(err)
		}
		return id
	}
	if !errors.Is(err, sql.ErrNoRows) {
		panic(err)
	}

	res, err := tx.Exec("INSERT INTO transactions(key, account, amount, status) VALUES(?, ?, ?, 'pending')", key, account, amount)
	if err != nil {
		panic(err)
	}
	id, err = res.LastInsertId()
	if err != nil {
		panic(err)
	}
	if err := tx.Commit(); err != nil {
		panic(err)
	}
	return id
}

func (l *Ledger) ProcessLoop(ch <-chan TxRequest) {
	for req := range ch {
		l.processOne(req)
	}
}

// processOne applies a transaction and records its completion in the same
// SQLite transaction. Thus a row is either pending with no account effect or
// completed with exactly one account effect, even across a SIGKILL.
func (l *Ledger) processOne(req TxRequest) {
	defer func() {
		if req.Done != nil {
			close(req.Done)
